// isUnreservedByte reports whether c is RFC 3986 unreserved (ALPHA / DIGIT /
// "-" / "." / "_" / "~"), the only bytes left literal in a group name.
func isUnreservedByte(c byte) bool {
	switch {
	case c >= 'A' && c <= 'Z', c >= 'a' && c <= 'z', c >= '0' && c <= '9':
		return true
	case c == '-', c == '.', c == '_', c == '~':
		return true
	default:
		return false
	}
}

